async(page)=>{
 const base='http://127.0.0.1:5173/',checks=[],errors=[],cloudCalls=[],tag=base.startsWith('http://127')?'local':'public';let backup,failure=''
 const check=(ok,label)=>{if(!ok)throw Error(label);checks.push(label)},onError=e=>errors.push(e.message),onRequest=r=>{if(/cloudbasegateway|tencentcloudapi|tcb-api/.test(r.url()))cloudCalls.push(r.url())}
 page.on('pageerror',onError);page.on('request',onRequest)
 const nav=async(route)=>{await page.goto(base+'?boundary='+Date.now()+'&demo=admin#/'+route);await page.locator('main').waitFor()}
 try{
  await nav('treehole?tab=forum');await page.getByRole('heading',{name:'同乡聊聊 · 留言广场',exact:true}).waitFor();backup=await page.evaluate(()=>Object.fromEntries(Object.keys(localStorage).filter(k=>k.startsWith('xsyj-')).map(k=>[k,localStorage.getItem(k)])))
  await page.getByRole('heading',{name:'云南同乡今天吃什么？',exact:true}).click();await page.getByLabel('楼层回复内容',{exact:true}).fill('隔离分页初始化回复');await page.getByRole('button',{name:'发布楼层回复',exact:true}).click();await page.getByRole('status').waitFor()
  await page.evaluate(()=>{const k='xsyj-demo:v1:admin',state=JSON.parse(localStorage.getItem(k));if(!state?.forum)throw Error('Fixture not initialized');const original=state.forum.topics.find(t=>t.id==='demo-forum-topic-1');state.forum.topics=Array.from({length:24},(_,i)=>({...original,id:i===0?'demo-forum-topic-1':'paging-topic-'+i,title:i===0?'分页与长文测试':'列表分页案例 '+i,body:i===0?'<img src=x onerror="window.__forumInjected=1">'+('LongUnbrokenText'.repeat(120)):'列表分页：第'+i+'条',status:'public',version:1,replyCount:i===0?25:0,sequence:String(1794150000000+i).padStart(13,'0')+'-0000000000000001'}));state.forum.replies=Array.from({length:25},(_,i)=>({id:'paging-reply-'+(i+1),topicId:'demo-forum-topic-1',owner_uid:i%2?'demo-admin':'demo-other',body:'分页楼层内容 '+(i+1),floor:i+1,replyToFloor:0,status:'public',version:1,sequence:String(1794150001000+i)+'-0000000000000001',createdAt:'2026-11-09'}));state.messages=[];localStorage.setItem(k,JSON.stringify(state))})
  await nav('treehole?tab=forum');await page.getByRole('button',{name:'查看更多话题',exact:true}).waitFor();check(await page.locator('.forum-topic-card').count()===20,'24条主题首屏只显示20条');await page.getByRole('button',{name:'查看更多话题',exact:true}).click();await page.getByRole('heading',{name:'分页与长文测试',exact:true}).waitFor();check(await page.locator('.forum-topic-card').count()===24,'加载更多追加其余主题且不遗漏')
  await page.getByRole('heading',{name:'分页与长文测试',exact:true}).click();await page.locator('#forum-floor-20').waitFor();check(await page.locator('.forum-floor').count()===20,'25楼首屏只显示1至20楼');check(await page.locator('.forum-body img').count()===0&&!await page.evaluate(()=>window.__forumInjected),'讨论HTML按文字显示，不执行标签');await page.getByRole('button',{name:'下一页楼层',exact:true}).click();await page.locator('#forum-floor-25').waitFor();check(await page.locator('.forum-floor').count()===5,'下一页显示21至25楼且不重号');await page.getByRole('button',{name:'上一页楼层',exact:true}).click();await page.locator('#forum-floor-1').waitFor();check(await page.locator('.forum-floor').count()===20,'返回上一页恢复前20层')
  await nav('forum/demo-forum-topic-1?floor=25');await page.locator('#forum-floor-25.is-linked').waitFor();check(await page.locator('#forum-floor-21').count()===1&&await page.locator('#forum-floor-1').count()===0,'指定第25楼直接读取第二页并高亮')
  for(const width of [320,390,1440]){await page.setViewportSize({width,height:844});check(await page.locator('.app-frame').evaluate(e=>e.scrollWidth<=e.clientWidth+1&&document.documentElement.scrollWidth<=innerWidth+1),'长段英文和HTML文字不造成横向溢出 '+width)}
  await page.evaluate(()=>{const k='xsyj-demo:v1:admin',s=JSON.parse(localStorage.getItem(k));s.profiles.find(p=>p.uid===s.actor).publishing_restricted=true;localStorage.setItem(k,JSON.stringify(s))});await nav('forum-compose');await page.getByRole('heading',{name:'暂时不能发布',exact:true}).waitFor();check(await page.getByRole('button',{name:'发布话题',exact:true}).count()===0,'限制发布账号在填写之前被拦截');await nav('forum/demo-forum-topic-1');await page.getByText('当前身份被限制发布，可查看原因并申请复核。',{exact:true}).waitFor();check(await page.getByRole('button',{name:'发布楼层回复',exact:true}).count()===0,'限制发布同样阻止楼层回复')
  await page.evaluate(()=>{const k='xsyj-demo:v1:admin',s=JSON.parse(localStorage.getItem(k)),p=s.profiles.find(p=>p.uid===s.actor);p.publishing_restricted=false;p.avatar_key='';localStorage.setItem(k,JSON.stringify(s))});await nav('forum-compose');await page.getByRole('heading',{name:'完善资料',exact:true}).waitFor();check(await page.getByLabel('话题标题',{exact:true}).count()===0,'缺少必填头像先完善资料，不能绕过发帖门槛')
  check(errors.length===0,'边界页面无运行时错误');check(cloudCalls.length===0,'批量案例仅在本机存储，不写真实数据库')
 }catch(e){failure=e.message;await page.screenshot({path:'D:/Desktop/小食云记-新网页版/docs/evidence/forum-boundaries-'+tag+'-failure-20261109.png'}).catch(()=>{})}finally{if(backup)await page.evaluate(original=>{for(const k of Object.keys(localStorage))if(k.startsWith('xsyj-'))localStorage.removeItem(k);for(const[k,v]of Object.entries(original))localStorage.setItem(k,v)},backup);page.off('pageerror',onError);page.off('request',onRequest)}
 return {base,checks,errors,cloudCalls,failure}
}
